// packages/shell/plugins/with-camera.ts (fixture: a config plugin that adds a permission)
import { AndroidConfig, withAndroidManifest } from 'expo/config-plugins';

const CAMERA = 'android.permission.CAMERA';

export default function withCamera(config: object): object {
  return withAndroidManifest(config, (mod) => {
    AndroidConfig.Permissions.ensurePermissions(mod.modResults, [CAMERA]);
    return mod;
  });
}
